        menu.Items.OfType<MenuItem>().Single(item=>Equals(item.Header,"Text area")).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Layout(view,size);var text=row.Elements.Single();var tools=editor.GetInlineTools(text);
