        var box=body.AddElement(row,"box");var nested=body.AddElement(row,"box",box);var choice=wizard.LibraryObjects.Where(item=>item.Kind=="element").Select(item=>(Choice:item,Source:wizard.GetLibraryObject(item.Source))).First(pair=>pair.Source?.Element?.Fields.Any(HyperlibHeaderLayouts.IsSlotContentField)==true&&pair.Source.Element.Fields.Any(field=>!HyperlibHeaderLayouts.IsSlotContentField(field)));
        var first=body.AddLibraryObject(row,choice.Choice.Source,choice.Source!,nested);body.AddLibraryObject(row,choice.Choice.Source,choice.Source!,nested);body.SelectedElement=first;Layout(view,size);tools=editor.GetInlineTools(first);Bound<TextBox>(tools,TextBox.TextProperty,first,nameof(first.SlotName)).Text="Interactive card";Layout(view,size);
