        Check(receipt,pageNav.Kind=="navigation"&&pageNav.Navigation.ShowPreviousNext&&pageNav.Navigation.IncludeHome&&!pageNav.Navigation.AutoPages&&!pageNav.Navigation.CollapseOnSmallScreens,"Nested Footer Page navigation defaults to previous/next and Work home without duplicating the full menu.");
        Bound<TextBox>(navTools,TextBox.TextProperty,pageNav.Navigation,nameof(pageNav.Navigation.HomeLabel)).Text="Back to this Work";Descendants<Expander>(navTools).Single(expander=>Equals(expander.Header,"Behavior")).IsExpanded=true;Layout(view,size);Bound<CheckBox>(navTools,ToggleButton.IsCheckedProperty,pageNav.Navigation,nameof(pageNav.Navigation.ShowPreviousNext)).SetCurrentValue(ToggleButton.IsCheckedProperty,false);Layout(view,size);
        Check(receipt,pageNav.BuildDefinition().Navigation!.HomeLabel=="Back to this Work"&&!pageNav.BuildDefinition().Navigation!.ShowPreviousNext,"Footer navigation behavior and labels update through the real inline controls.");
        var repeated=footer.AddElement(footerRow,"text",footerBox);Layout(view,size);var repeatedTools=footerEditor.GetInlineTools(repeated);var repeatedText=Descendants<TextBox>(repeatedTools).Single(control=>AutomationProperties.GetName(control)=="Footer text");repeatedText.Text="© Your project";Check(receipt,!repeated.IsContentSlot&&repeated.Text=="© Your project","Footer text remains repeated template content with its normal editor.");
